import java.util.*;
import java.io.*;

public class Main {
    static final int Lg = 18;
    static final int Tw = 1 << Lg;
    static final int Max = Tw + 10;
    static int[][] matrix = new int[Max][Lg + 3];
    static int[] buffer = new int[Lg + 3];
    static int[] buffer2 = new int[Lg + 3];
    static int[] factorial = new int[Max];
    static int[] inv_factorial = new int[Max];
    static int N, n, mod = 1000000007;

    static int mod_exp(int base, int exp) {
        int res = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (int) ((long) res * base % mod);
            base = (int) ((long) base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static void array_add(int[] a, int[] b, int size) {
        for (int i = 0; i <= size; i++) {
            a[i] = (a[i] + b[i]) % mod;
        }
    }

    static void array_subtract(int[] a, int[] b, int size) {
        for (int i = 0; i <= size; i++) {
            a[i] = (a[i] - b[i]) % mod;
            if (a[i] < 0) a[i] += mod;
        }
    }

    static void array_multiply(int[] res, int[] a, int[] b, int size) {
        Arrays.fill(buffer, 0);
        for (int i = 0; i <= size; i++) {
            for (int j = 0; j <= i; j++) {
                buffer[i] = (int) ((buffer[i] + (long) a[j] * b[i - j]) % mod);
            }
        }
        System.arraycopy(buffer, 0, res, 0, size + 1);
    }

    static void forward_transform(int[][] a, int size) {
        for (int i = 0; i < N; i++) {
            for (int msk = n; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    array_add(a[msk], a[msk ^ (1 << i)], size);
                }
            }
        }
    }

    static void inverse_transform(int[][] a, int size) {
        for (int i = 0; i < N; i++) {
            for (int msk = n; msk >= 0; msk--) {
                if (((msk >> i) & 1) == 1) {
                    array_subtract(a[msk], a[msk ^ (1 << i)], size);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        int K = sc.nextInt();
        n = sc.nextInt();
        mod = sc.nextInt();

        int total = mod_exp(K, n);
        if ((n & 1) == 1) {
            System.out.println(total);
            return;
        }

        N = Integer.bitCount(n);
        int original_n = n;

        List<Integer> pos = new ArrayList<>();
        for (int i = 0; i < Lg; i++) {
            if (((n >> i) & 1) == 1) {
                pos.add(i);
            }
        }

        n = (1 << N) - 1;

        factorial[0] = 1;
        for (int i = 1; i < Max; i++) {
            factorial[i] = (int) ((long) i * factorial[i - 1] % mod);
        }

        inv_factorial[Max - 1] = mod_exp(factorial[Max - 1], mod - 2);
        for (int i = Max - 2; i >= 0; i--) {
            inv_factorial[i] = (int) ((long) (i + 1) * inv_factorial[i + 1] % mod);
        }

        for (int i = 0; i <= n; i++) {
            int val = 0;
            for (int j = 0; j < N; j++) {
                if (((i >> j) & 1) == 1) {
                    val += (1 << pos.get(j));
                }
            }
            matrix[i][Integer.bitCount(i)] = inv_factorial[val];
        }

        forward_transform(matrix, N);
        for (int i = 0; i <= n; i++) {
            int K_copy = K;
            Arrays.fill(buffer2, 0);
            buffer2[0] = 1;
            while (K_copy > 0) {
                if ((K_copy & 1) == 1) {
                    array_multiply(buffer2, buffer2, matrix[i], N);
                }
                array_multiply(matrix[i], matrix[i], matrix[i], N);
                K_copy >>= 1;
            }
            System.arraycopy(buffer2, 0, matrix[i], 0, N + 1);
        }
        inverse_transform(matrix, N);
        int answer = (total - (int) ((long) matrix[n][N] * factorial[original_n] % mod)) % mod;
        if (answer < 0) answer += mod;
        System.out.println(answer);
    }
}
